module LFSR (
    output reg [3:0] out,
    input clk,
    input rst
);
always @(posedge clk or posedge rst) begin
    if (rst) begin
        out <= 4'b0000;
    end else begin
        reg [3:0] temp;
        temp = out << 1;
        temp[0] = ~((out[3] ^ out[2]));
        out <= temp;
    end
end
endmodule
